<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';api_headers();$raw=json_decode(file_get_contents('php://input'),true)?:[];$code=(string)($raw['code']??'');$redirect=(string)($raw['redirect_uri']??'');if($code===''||$redirect==='')json_response(['ok'=>false,'error'=>['code'=>'INVALID_REQUEST']],422);$hash=hash('sha256',$code);$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT id,user_id FROM extension_auth_codes WHERE code_hash=? AND redirect_uri=? AND used_at IS NULL AND expires_at>NOW() FOR UPDATE');$q->execute([$hash,$redirect]);$row=$q->fetch();if(!$row){$pdo->rollBack();json_response(['ok'=>false,'error'=>['code'=>'INVALID_OR_EXPIRED_CODE']],401);}$token=bin2hex(random_bytes(32));$pdo->prepare('UPDATE extension_auth_codes SET used_at=NOW() WHERE id=?')->execute([$row['id']]);$q=$pdo->prepare('INSERT INTO extension_sessions(user_id,token_hash,device_name) VALUES(?,?,?)');$q->execute([$row['user_id'],hash('sha256',$token),substr((string)($raw['device_name']??'Chrome extension'),0,190)]);$pdo->commit();json_response(['ok'=>true,'data'=>['token'=>$token]],201);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['ok'=>false,'error'=>['code'=>'TOKEN_EXCHANGE_FAILED']],500);}
